```javascript run
let daftarTugas = [];

function tambahTugas(teks) {
  const tugasBaru = { id: daftarTugas.length + 1, teks: teks, selesai: false };
  daftarTugas.push(tugasBaru);
}

function tampilkanTugas(daftar) {
  for (const tugas of daftar) {
    const tanda = tugas.selesai ? "[x]" : "[ ]";
    console.log(`${tanda} ${tugas.id}. ${tugas.teks}`);
  }
}

function tandaiSelesai(id) {
  const tugas = daftarTugas.find(t => t.id === id);
  if (!tugas) return;
  tugas.selesai = true;
}

function hapusTugas(id) {
  daftarTugas = daftarTugas.filter(t => t.id !== id);
}

function hitungStatistik(daftar) {
  const totalTugas = daftar.length;
  const tugasSelesai = daftar.filter(t => t.selesai).length;
  return { totalTugas, tugasSelesai };
}

tambahTugas("Belajar JavaScript");
tambahTugas("Beli bahan masakan");
tambahTugas("Cuci motor");
tandaiSelesai(1);
hapusTugas(3);

console.log("=== Daftar Tugas ===");
tampilkanTugas(daftarTugas);
console.log("=== Statistik ===");
console.log(hitungStatistik(daftarTugas));
```

