function tambahTugas(teks) {
  daftarTugas.push({ id: daftarTugas.length + 1, teks: teks, selesai: false });
}
function tandaiSelesai(id) {
  const tugas = daftarTugas.find(t => t.id === id);
  if (!tugas) return;
  tugas.selesai = true;
}
function hitungStatistik(daftar) {
  return { total: daftar.length, selesai: daftar.filter(t => t.selesai).length };
}
